export type GithubDestinationPayload = {
    branch: string;
    relativePath: string;
    url: string;
};
export type AzureDestinationPayload = {
    organizationId: string;
    projectId: string;
    repositoryId: string;
    branch: string;
    relativePath: string;
};
export type BitbucketDestinationPayload = {
    workspaceSlug: string;
    projectKey: string;
    repoSlug: string;
    branch: string;
    relativePath: string;
};
export type GitlabDestinationPayload = {
    projectId: string;
    branch: string;
    relativePath: string;
};
export type DocumentationDestinationPayload = {
    environment: "Live" | "Preview";
};
export type ExporterJobDestination = {
    azure: AzureDestinationPayload | null | undefined;
    bitbucket: BitbucketDestinationPayload | null | undefined;
    documentation: DocumentationDestinationPayload | null | undefined;
    github: GithubDestinationPayload | null | undefined;
    gitlab: GitlabDestinationPayload | null | undefined;
    s3: Record<string, any> | undefined;
    webhookUrl: null | undefined;
};
